import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class MistSpan {
    static final int ALIGN = 32;
    static final int PIN_SIZE = 48;

    public static final class Scan {
        public final List<byte[]> ids = new ArrayList<byte[]>();
        public boolean bad;
    }

    static final class Record {
        byte[] id;
        byte[] payload;
    }

    public static Scan scan(Path silo) throws Exception {
        byte[] pins = read(silo.resolve("pin.bin"));
        byte[] blob = read(silo.resolve("blob.bin"));
        Scan result = new Scan();
        if (pins.length % PIN_SIZE != 0) result.bad = true;
        for (int pos = 0; pos + PIN_SIZE <= pins.length; pos += PIN_SIZE) {
            Record r = parse(pins, pos, blob);
            if (r == null) result.bad = true;
            else result.ids.add(r.id);
        }
        return result;
    }

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        if (wanted == null || wanted.length != 16) return null;
        byte[] pins = read(silo.resolve("pin.bin"));
        byte[] blob = read(silo.resolve("blob.bin"));
        for (int pos = 0; pos + PIN_SIZE <= pins.length; pos += PIN_SIZE) {
            Record r = parse(pins, pos, blob);
            if (r != null && Arrays.equals(r.id, wanted)) return r.payload;
        }
        return null;
    }

    private static byte[] read(Path p) throws Exception {
        return Files.exists(p) ? Files.readAllBytes(p) : new byte[0];
    }

    private static Record parse(byte[] pins, int pos, byte[] blob) throws Exception {
        if (pins[pos] != 'P' || pins[pos + 1] != 'N' ||
                pins[pos + 2] != '0' || pins[pos + 3] != '1') return null;
        ByteBuffer bb = ByteBuffer.wrap(pins, pos, PIN_SIZE);
        bb.position(pos + 4);
        long off = bb.getLong();
        int len = bb.getInt();
        int crc = bb.getInt();
        byte[] id = new byte[16];
        bb.get(id);
        if (off < 0 || (off % ALIGN) != 0 || len < 0) return null;
        long rec = 4L + len;
        long padded = rec + ((ALIGN - (rec % ALIGN)) % ALIGN);
        if (off > blob.length || padded > blob.length - off || off > Integer.MAX_VALUE) return null;
        int at = (int) off;
        if (ByteBuffer.wrap(blob, at, 4).getInt() != len) return null;
        byte[] payload = Arrays.copyOfRange(blob, at + 4, at + 4 + len);
        if (payload.length > 0 && allZero(payload)) return null;
        if (Crc.of(payload) != crc) return null;
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(payload);
        if (!Arrays.equals(id, Arrays.copyOf(digest, 16))) return null;
        Record r = new Record();
        r.id = id;
        r.payload = payload;
        return r;
    }

    private static boolean allZero(byte[] a) {
        for (byte b : a) if (b != 0) return false;
        return true;
    }
}
