import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.LinkedHashSet;
import java.util.Set;

public class HueWalk {
    public static int orb_n(Path blob, Path pin, Path card) throws Exception {
        MistSpan.Scan scan = MistSpan.scan(blob.getParent());
        Set<String> held = new LinkedHashSet<String>();
        for (byte[] id : scan.ids) held.add(hex(id));
        String note = scan.bad ? "gap" : "ok";
        String kind = scan.bad ? "void" : "live";
        String json = "{\"held\":" + arr(held) + ",\"note\":\"" + note
                + "\",\"kind\":\"" + kind + "\"}";
        Path tmp = card.resolveSibling(card.getFileName().toString() + ".tmp");
        Files.writeString(tmp, json);
        try {
            Files.move(tmp, card, StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING);
        } catch (java.nio.file.AtomicMoveNotSupportedException e) {
            Files.move(tmp, card, StandardCopyOption.REPLACE_EXISTING);
        }
        return scan.bad ? 1 : 0;
    }

    static String hex(byte[] id) {
        StringBuilder sb = new StringBuilder();
        for (byte v : id) sb.append(String.format("%02x", v & 0xff));
        return sb.toString();
    }

    static String arr(Set<String> held) {
        StringBuilder sb = new StringBuilder("[");
        boolean comma = false;
        for (String id : held) {
            if (comma) sb.append(',');
            sb.append('"').append(id).append('"');
            comma = true;
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        Path silo = Path.of("/app/silo");
        System.exit(orb_n(silo.resolve("blob.bin"), silo.resolve("pin.bin"),
                silo.resolve("wake.json")));
    }
}
